var t=`1110-nasi-katok`;var a=`world-1110`;var n=`BN`;var s=`southeast-asia`;var o=4;var r=93;var d={en:`Nasi Katok`,ua:`Насі каток`};var c={en:`Nasi Katok is a dish from Brunei prepared with chicken thigh, light soy sauce, garlic, jasmine rice. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Насі каток, страва кухні країни Бруней, яку готують із таких продуктів: куряче стегно, світлий соєвий соус, часник, рис жасмин. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 45 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 45 хвилин.`,t:[`marinating`],m:45,i:[[`chicken-thigh`,850,`g`],[`light-soy-sauce`,45,`ml`],[`garlic`,4,`clove`],[`ground-turmeric`,5,`g`]]},{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 25 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 25 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:25,i:[[`jasmine-rice`,450,`g`],[`water`,690,`ml`]]},{en:`Fry shaped portions in small batches in oil heated to about 170–175°C for about 18 minutes, until golden; drain on a rack.`,ua:`Смажте сформовані вироби невеликими партіями в олії температурою приблизно 170–175°C близько 18 хвилин до золотистості; викладіть на решітку.`,t:[`deep-frying`],m:18,i:[[`canola-oil`,650,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`red-salsa`,130,`g`],[`bird-s-eye-chili`,2,`pcs`]]}];var u={slug:t,id:a,country:`BN`,region:s,servings:4,minutes:93,title:d,text:c,steps:l};export{n as country,u as default,a as id,r as minutes,s as region,o as servings,t as slug,l as steps,c as text,d as title};